#!/usr/bin/env bash
# Generated by fem-client. Python is managed only through uv (D20); engines run as containers.
set -euo pipefail
cd "$(dirname "$0")"
echo '== geometry and mesh (gmsh)'
uv run --no-project --with 'gmsh==4.13.1' python geometry.py
echo '== mesh conversion to med (meshlane) and round-trip check'
uv run --no-project --with 'meshlane' --with numpy python convert_mesh.py med
echo '== Code_Aster'
podman run --rm -v "$PWD":/work:Z -w /work simvia/code_aster:stable run_aster job.export
test -f results.json && echo '== done'
